#include <cuda_runtime.h>
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define BEM_TABLE_QUAL static __device__ __constant__
#define BEM_HD static __device__ __forceinline__
#include "bem_real_solver.h"
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s:%d: %s\n",__FILE__,__LINE__,cudaGetErrorString(e));exit(2);}}while(0)
typedef struct __attribute__((packed)){char magic[8];uint32_t version;uint64_t n;uint32_t nf,node_per_step,steps;} Header;
static int cmpf(const void*a,const void*b){float x=*(const float*)a,y=*(const float*)b;return(x>y)-(x<y);}

__host__ __device__ __forceinline__ uint64_t mix64(uint64_t x){x^=x>>30;x*=0xbf58476d1ce4e5b9ULL;x^=x>>27;x*=0x94d049bb133111ebULL;return x^(x>>31);}
__host__ __device__ __forceinline__ int is_hard(uint64_t i,uint64_t threshold,uint64_t seed){return mix64(i+0x9e3779b97f4a7c15ULL*(seed+1))<threshold;}
__device__ __forceinline__ double easy_work(double x,double vx,double vy,double th,unsigned node){int v=0;double y=x;
#pragma unroll 4
  for(int k=0;k<4;k++)y=fma(0.0,bem_residual(x+1e-9*k,vx,vy,th,node,&v),y);return y;}
__device__ __forceinline__ double hard_work(uint64_t i,const double*vx,const double*vy,const double*th,const double*hint,uint8_t*ok){double r;int g=bem_solve_robust_nearest(vx[i],vy[i],th[i],hint[i],(unsigned)(i%51)%17,1,&r);*ok=(uint8_t)g;return r;}
__device__ __forceinline__ void warp_enqueue(uint64_t i,int hard,uint64_t*q,uint32_t*c){unsigned active=__activemask(),m=__ballot_sync(active,hard);if(!hard)return;int lane=threadIdx.x&31,leader=__ffs(m)-1;uint32_t base=0;if(lane==leader)base=atomicAdd(c,(uint32_t)__popc(m));base=__shfl_sync(active,base,leader);unsigned lower=lane?((1u<<lane)-1u):0u;q[base+__popc(m&lower)]=i;}

__global__ void inline_kernel(const double*vx,const double*vy,const double*th,const double*hint,double*out,uint8_t*ok,uint64_t n,uint64_t threshold,uint64_t seed){uint64_t i=(uint64_t)blockIdx.x*blockDim.x+threadIdx.x;if(i>=n)return;if(is_hard(i,threshold,seed))out[i]=hard_work(i,vx,vy,th,hint,&ok[i]);else{out[i]=easy_work(hint[i],vx[i],vy[i],th[i],(unsigned)(i%51)%17);ok[i]=1;}}
__global__ void classify_global(const double*vx,const double*vy,const double*th,const double*hint,double*out,uint8_t*ok,uint64_t*q,uint32_t*c,uint64_t n,uint64_t threshold,uint64_t seed){uint64_t i=(uint64_t)blockIdx.x*blockDim.x+threadIdx.x;int h=i<n&&is_hard(i,threshold,seed);if(i<n&&!h){out[i]=easy_work(hint[i],vx[i],vy[i],th[i],(unsigned)(i%51)%17);ok[i]=1;}warp_enqueue(i,h,q,c);}
__global__ void global_fallback(const double*vx,const double*vy,const double*th,const double*hint,double*out,uint8_t*ok,const uint64_t*q,const uint32_t*c,uint64_t n){uint64_t s=(uint64_t)blockIdx.x*blockDim.x+threadIdx.x;uint32_t m=*c;if(s<m&&s<n){uint64_t i=q[s];out[i]=hard_work(i,vx,vy,th,hint,&ok[i]);}}
__global__ void block_kernel(const double*vx,const double*vy,const double*th,const double*hint,double*out,uint8_t*ok,uint64_t n,uint64_t threshold,uint64_t seed){__shared__ uint64_t q[256];__shared__ uint32_t count;if(threadIdx.x==0)count=0;__syncthreads();uint64_t i=(uint64_t)blockIdx.x*blockDim.x+threadIdx.x;if(i<n){if(is_hard(i,threshold,seed)){uint32_t s=atomicAdd(&count,1u);q[s]=i;}else{out[i]=easy_work(hint[i],vx[i],vy[i],th[i],(unsigned)(i%51)%17);ok[i]=1;}}__syncthreads();for(uint32_t s=threadIdx.x;s<count;s+=blockDim.x){uint64_t j=q[s];out[j]=hard_work(j,vx,vy,th,hint,&ok[j]);}}
__global__ void warp_kernel(const double*vx,const double*vy,const double*th,const double*hint,double*out,uint8_t*ok,uint64_t n,uint64_t threshold,uint64_t seed){uint64_t i=(uint64_t)blockIdx.x*blockDim.x+threadIdx.x;unsigned active=__activemask(),m=__ballot_sync(active,i<n&&is_hard(i,threshold,seed));if(i<n&&!(m&(1u<<(threadIdx.x&31)))){out[i]=easy_work(hint[i],vx[i],vy[i],th[i],(unsigned)(i%51)%17);ok[i]=1;}int lane=threadIdx.x&31,count=__popc(m);if(lane<count){int source=__ffs(m)-1;for(int k=0;k<lane;k++){m&=m-1;source=__ffs(m)-1;}uint64_t base=i-(uint64_t)lane,j=base+(uint64_t)source;if(j<n)out[j]=hard_work(j,vx,vy,th,hint,&ok[j]);}}

static int auto_mode(double p){if(p<0.0005||p>=0.9)return 0;if(p<0.03)return 2;if(p<0.075)return 3;if(p<0.6)return 2;if(p<0.9)return 3;return 0;}
static void launch(int mode,const double*vx,const double*vy,const double*th,const double*hint,double*out,uint8_t*ok,uint64_t*q,uint32_t*c,uint64_t n,uint64_t threshold,uint64_t seed){int b=(int)((n+255)/256);if(mode==0)inline_kernel<<<b,256>>>(vx,vy,th,hint,out,ok,n,threshold,seed);else if(mode==1)warp_kernel<<<b,256>>>(vx,vy,th,hint,out,ok,n,threshold,seed);else if(mode==2)block_kernel<<<b,256>>>(vx,vy,th,hint,out,ok,n,threshold,seed);else{CK(cudaMemsetAsync(c,0,sizeof(uint32_t)));classify_global<<<b,256>>>(vx,vy,th,hint,out,ok,q,c,n,threshold,seed);global_fallback<<<b,256>>>(vx,vy,th,hint,out,ok,q,c,n);}}
int main(int argc,char**argv){if(argc<4){fprintf(stderr,"usage: %s dataset.bin mode p [repeats] [warmups] [seed]\n",argv[0]);return 2;}int requested=atoi(argv[2]);double p=strtod(argv[3],0);int reps=argc>4?atoi(argv[4]):30,warm=argc>5?atoi(argv[5]):10;uint64_t seed=argc>6?strtoull(argv[6],0,10):0;int mode=requested==4?auto_mode(p):requested;if(mode<0||mode>3||p<0||p>1)return 2;uint64_t threshold=p>=1?UINT64_MAX:(uint64_t)(p*18446744073709551615.0L);FILE*f=fopen(argv[1],"rb");Header h;if(!f||fread(&h,1,sizeof h,f)!=sizeof h||memcmp(h.magic,"BEMREAL2",8)||h.nf!=5)return 2;size_t db=(size_t)h.n*5*sizeof(double),rb=(size_t)h.n*sizeof(double),sb=(size_t)h.n;double*hbuf;uint8_t*hflags,*hok;CK(cudaMallocHost(&hbuf,db));CK(cudaMallocHost(&hflags,sb));CK(cudaMallocHost(&hok,sb));if(fread(hbuf,1,db,f)!=db||fread(hflags,1,sb,f)!=sb)return 2;fclose(f);double*dbuf,*out;uint8_t*ok;uint64_t*q;uint32_t*c;CK(cudaMalloc(&dbuf,db));CK(cudaMalloc(&out,rb));CK(cudaMalloc(&ok,sb));CK(cudaMalloc(&q,(size_t)h.n*sizeof(uint64_t)));CK(cudaMalloc(&c,sizeof(uint32_t)));CK(cudaMemcpy(dbuf,hbuf,db,cudaMemcpyHostToDevice));double*vx=dbuf,*vy=vx+h.n,*th=vy+h.n,*hint=dbuf+4*h.n;for(int k=0;k<warm;k++)launch(mode,vx,vy,th,hint,out,ok,q,c,h.n,threshold,seed);CK(cudaDeviceSynchronize());float*t=(float*)malloc(reps*sizeof(float)),*s=(float*)malloc(reps*sizeof(float));cudaEvent_t a,b;CK(cudaEventCreate(&a));CK(cudaEventCreate(&b));for(int r=0;r<reps;r++){CK(cudaEventRecord(a));launch(mode,vx,vy,th,hint,out,ok,q,c,h.n,threshold,seed);CK(cudaEventRecord(b));CK(cudaEventSynchronize(b));CK(cudaEventElapsedTime(&t[r],a,b));}CK(cudaMemcpy(hok,ok,sb,cudaMemcpyDeviceToHost));size_t fail=0,hard=0;for(uint64_t i=0;i<h.n;i++){fail+=!hok[i];hard+=is_hard(i,threshold,seed);}memcpy(s,t,reps*sizeof(float));qsort(s,reps,sizeof(float),cmpf);double qwarp=1.0-pow(1.0-p,32.0);const char*name[]={"inline","warp_local","block_local","global_compact"};printf("{\"requested_mode\":\"%s\",\"mode\":\"%s\",\"seed\":%" PRIu64 ",\"p_requested\":%.9g,\"p_observed\":%.17g,\"q_warp_model\":%.17g,\"records\":%" PRIu64 ",\"hard\":%zu,\"failures\":%zu,\"repetitions\":%d,\"kernel_median_ms\":%.9g,\"times_ms\":[",requested==4?"auto":name[mode],name[mode],seed,p,(double)hard/h.n,qwarp,h.n,hard,fail,reps,s[reps/2]);for(int r=0;r<reps;r++)printf("%s%.9g",r?",":"",t[r]);printf("]}\n");free(s);free(t);cudaFree(c);cudaFree(q);cudaFree(ok);cudaFree(out);cudaFree(dbuf);cudaFreeHost(hok);cudaFreeHost(hflags);cudaFreeHost(hbuf);return fail?3:0;}
